```xUnit Test Cases
// GUI Test Suite for U17_GUI

[Test]
public class U17GUI_Tests
{
    [Fact]
    public void DisplayPatientPressure_Should_ShowCorrectValue()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);

        // Act
        gui.DisplayPatientPressure();

        // Assert
        Assert.Equal(controller.Pressure, gui.DisplayedPressure);
    }

    [Fact]
    public void GraphRefreshRate_Should_BeAtLeast20Hz()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        var timer = gui.StartGraphRefreshTimer();
        // Assert
        Assert.True(timer.ElapsedMilliseconds >= 50);
    }

    [Fact]
    public void GraphDuration_Should_Be30Seconds()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        var timer = gui.StartGraphRefreshTimer();
        // Assert
        Assert.Equal(timer.ElapsedMilliseconds, 30000);
    }

    [Fact]
    public void DisplayInspiratoryTidalVolume_Should_BeInRange0To1000mL()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        gui.DisplayInspiratoryTidalVolume();
        // Assert
        Assert.InRange(gui.DisplayedTidalVolume, 0, 1000);
    }

    [Fact]
    public void DisplayInspirationExpirationRatio_Should_BeInRange10To1To200()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        gui.DisplayInspirationExpirationRatio();
        // Assert
        Assert.InRange(gui.DisplayedRatio, 10, 1.2);
    }

    [Fact]
    public void DisplayPEEP_Should_BeInIncrementsOf1cmH2O()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        gui.DisplayPEEP();
        // Assert
        Assert.Equal(gui.DisplayedPEEP, 1);
    }

    [Fact]
    public void DisplayVolumeGraph_Should_BeCorrect()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        gui.DisplayVolumeGraph();
        // Assert
        Assert.Equal(gui.DisplayedVolume, controller.Volume);
    }

    [Fact]
    public void FlowRateGraph_Should_BeAtLeast20Hz()
    {
        // Arrange
        var controller = new MockController();
        var gui = new U17GUI(controller);
        controller.SetPressure(100);

        // Act
        gui.StartFlowRateGraphTimer();
        // Assert
        Assert.True(timer.ElapsedMilliseconds >= 50);
    }
}
